import{_ as t,c as l,o as a,ah as e}from"./chunks/framework.Ch_PcVtW.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"scripts/output/PART2/0/0_context_summary.md","filePath":"scripts/output/PART2/0/0_context_summary.md"}'),r={name:"scripts/output/PART2/0/0_context_summary.md"};function o(n,i,s,_,c,u){return a(),l("div",null,[...i[0]||(i[0]=[e('<h2 id="_1-本篇主题与主要内容概述" tabindex="-1">1) 本篇主题与主要内容概述 <a class="header-anchor" href="#_1-本篇主题与主要内容概述" aria-label="Permalink to &quot;1) 本篇主题与主要内容概述&quot;">​</a></h2><p>本篇以时间线形式梳理BMSG在2023年的主要发展轨迹，涵盖MAZZEL从企划到出道、BE:FIRST与SKY-HI的音乐发行及演出活动、BMSG FES与D.U.N.K.项目的推进、粉丝社区B-Town的改版，以及BMSG成立三周年等重要节点。同时记录了BMSG与行业人士的交流活动，并以“No No Girls”女子组合选秀企划的启动作为年度收束，呈现公司在艺人培养、现场演出、音乐内容和行业合作方面的持续扩张。</p><h2 id="_2-人物-术语-语气风险点" tabindex="-1">2) 人物/术语/语气风险点 <a class="header-anchor" href="#_2-人物-术语-语气风险点" aria-label="Permalink to &quot;2) 人物/术语/语气风险点&quot;">​</a></h2><ul><li><strong>BMSG、SKY-HI、BE:FIRST、MAZZEL、edhiii boi、REIKO</strong>均为专有名词，须统一保留官方英文拼写。</li><li>**D.U.N.K.**的全称为“DANCE UNIVERSE NEVER KILLED”，不宜意译或擅自改写。</li><li><strong>B-Town</strong>为粉丝社区名称；“オンラインサロン”应根据语境译为“线上会员社区”或“线上社群”，避免简单译作普通论坛。</li><li><strong>Showcase、One Man Tour、Arena Tour、Split Single、Live Documentary Film</strong>等音乐行业术语需保持专业准确。</li><li>“完走”用于巡演语境，宜译为“顺利完成巡演”，不宜直译为“跑完全程”。</li><li>“結成”“デビュー”“リリース”“放送開始”“開催”分别对应成立/组建、出道、发行、开播、举办，不应混用。</li><li>时间线整体采用客观、简洁、新闻纪年式语气，不宜加入评价性形容词。</li><li>注意原文书名号和引号存在个别不完整或混用情况，如《BE:the ONE》、〈BUTTERFLY〉，翻译时应统一格式。</li><li>“BMSG設立3周年”应明确为“BMSG成立三周年”，避免译成“创立纪念日”等过度扩写。</li></ul><h2 id="_3-翻译时建议重点" tabindex="-1">3) 翻译时建议重点 <a class="header-anchor" href="#_3-翻译时建议重点" aria-label="Permalink to &quot;3) 翻译时建议重点&quot;">​</a></h2><ul><li>保留原文日期顺序与条目结构，统一使用“2023年X月X日”格式。</li><li>首次出现的英文项目可保留英文，并在必要时补充常用中文说明，例如“live documentary film（演唱会纪录片）”。</li><li>官方作品名、节目名、演出名和企划名原则上保留原文，不对英文标题进行非官方翻译。</li><li>准确区分“节目开播”“音乐节目上线”“演出举办”“作品发行”等事件类型。</li><li>“初の”“2度目となる”“自身最大規模”等信息应完整保留，体现年度发展规模与阶段性成果。</li><li>涉及场馆时，统一译法，如“有明Arena”“幕张展览馆”“东京体育馆”“大阪城Hall”“京瓷巨蛋大阪”。</li><li>语言应简练客观，体现出版年表的记录感，避免添加原文没有的背景、评价或因果关系。</li></ul>',6)])])}const h=t(r,[["render",o]]);export{d as __pageData,h as default};
